$ErrorActionPreference='Stop'
$zip=Join-Path $env:TEMP 'MGS-PC-Forensics-Collector.zip'
[IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(@'

'@))
$dir=Join-Path $env:TEMP 'MGS-PC-Forensics-Collector'
